import net.minecraft.util.math.BlockPos;
import net.minecraftforge.items.wrapper.InvWrapper;

/** Actual released IInventory and Forge wrapper calls; no copied expected behavior. */
public final class StandaloneReaderInventoryLegacyChecks {
 private static final String[] OPS={"set","setInvalid","decrZero","decrOne","decrMany","remove","clear","insertSimulate","insert","extractSimulate","extract"};
 private static ItemStack input(boolean chip,int choice,int count){if(choice==0)return ItemStack.EMPTY;if(choice==11)return new ItemStack(net.minecraft.init.Items.STICK,count);int company=choice==1?-1:choice==9?7:choice==10?2:choice-2;return new ItemStack(choice==10?(chip?ModItems.ACCESS_CARD:ModItems.DATA_CHIP):(chip?ModItems.DATA_CHIP:ModItems.ACCESS_CARD),count,company);}
 private static JsonObject stack(ItemStack stack){JsonObject out=new JsonObject();out.addProperty("count",stack.getCount());if(!stack.isEmpty()){out.addProperty("kind",stack.getItem()==ModItems.DATA_CHIP?"chip":stack.getItem()==ModItems.ACCESS_CARD?"card":"other");out.addProperty("company",stack.getMetadata());}return out;}
 public static void main(String[] args)throws Exception {
  net.minecraft.init.Bootstrap.register();net.minecraftforge.fml.common.registry.GameRegistry.registerTileEntity(TileEntityTokenSlot.class,new net.minecraft.util.ResourceLocation("vandorlabs","token_slot"));net.minecraftforge.fml.common.registry.ForgeRegistries.ITEMS.register(ModItems.ACCESS_CARD);net.minecraftforge.fml.common.registry.ForgeRegistries.ITEMS.register(ModItems.DATA_CHIP);exportCases();
 }
 private static JsonArray hoppers(){JsonArray rows=new JsonArray();for(boolean chip:new boolean[]{false,true})for(int behavior=0;behavior<4;behavior++)for(int filter=0;filter<2;filter++)for(boolean returning:new boolean[]{false,true})for(boolean extracting:new boolean[]{false,true})for(net.minecraft.util.EnumFacing direction:new net.minecraft.util.EnumFacing[]{net.minecraft.util.EnumFacing.DOWN,net.minecraft.util.EnumFacing.NORTH,net.minecraft.util.EnumFacing.SOUTH,net.minecraft.util.EnumFacing.WEST,net.minecraft.util.EnumFacing.EAST}){
  NonRenderingChecks.MemoryWorld world=new NonRenderingChecks.MemoryWorld(false);world.time=100;BlockPos readerPos=new BlockPos(0,80,0);BlockTokenSlot block=new BlockTokenSlot(chip?"data_chip_slot":"access_card_slot",chip);world.setBlockState(readerPos,block.getDefaultState(),2);TileEntityTokenSlot tile=(TileEntityTokenSlot)world.getTileEntity(readerPos);NBTTagCompound raw=new NBTTagCompound();raw.setBoolean("ChipSlot",chip);raw.setBoolean("AnyToken",filter==0);raw.setInteger("AllowedTokens",8);raw.setInteger("TokenBehavior",behavior);if(extracting)raw.setTag("InsertedToken",new ItemStack(chip?ModItems.DATA_CHIP:ModItems.ACCESS_CARD,1,2).writeToNBT(new NBTTagCompound()));if(returning)raw.setUniqueId("TokenReturnTo",new java.util.UUID(17,29));tile.readFromNBT(raw);BlockPos hopperPos=extracting?readerPos.down():readerPos.offset(direction.getOpposite());world.setBlockState(hopperPos,net.minecraft.init.Blocks.HOPPER.getDefaultState().withProperty(net.minecraft.block.BlockHopper.FACING,direction),2);net.minecraft.tileentity.TileEntityHopper hopper=(net.minecraft.tileentity.TileEntityHopper)world.getTileEntity(hopperPos);if(!extracting)hopper.setInventorySlotContents(0,new ItemStack(chip?ModItems.DATA_CHIP:ModItems.ACCESS_CARD,3,2));hopper.setTransferCooldown(0);hopper.update();JsonObject row=new JsonObject();row.addProperty("chip",chip);row.addProperty("behavior",behavior);row.addProperty("filter",filter);row.addProperty("returning",returning);row.addProperty("extracting",extracting);row.addProperty("direction",direction.getIndex());int total=0;for(int slot=0;slot<hopper.getSizeInventory();slot++)total+=hopper.getStackInSlot(slot).getCount();row.addProperty("hopperCount",total);row.add("owned",stack(tile.getStackInSlot(0)));row.addProperty("output",tile.getOutputLevel());rows.add(row);
 }return rows;}
 private static void exportCases()throws Exception {
  JsonArray rows=new JsonArray();NonRenderingChecks.MemoryWorld world=new NonRenderingChecks.MemoryWorld(false);world.time=100;BlockPos pos=new BlockPos(0,80,0);
  for(boolean chip:new boolean[]{false,true}){BlockTokenSlot block=new BlockTokenSlot(chip?"data_chip_slot":"access_card_slot",chip);world.states.put(pos,block.getDefaultState());
   for(int behavior=0;behavior<4;behavior++)for(int filter=0;filter<3;filter++)for(boolean returning:new boolean[]{false,true})for(boolean occupied:new boolean[]{false,true})for(int choice=0;choice<12;choice++)for(int count:new int[]{1,64})for(String op:OPS){
    TileEntityTokenSlot tile=new TileEntityTokenSlot(chip);tile.setWorld(world);tile.setPos(pos);world.tiles.put(pos,tile);NBTTagCompound raw=new NBTTagCompound();raw.setBoolean("ChipSlot",chip);raw.setBoolean("AnyToken",filter==0);raw.setInteger("AllowedTokens",filter==1?4:8);raw.setInteger("TokenBehavior",behavior);raw.setLong("TokenPulseUntil",110);raw.setLong("TokenInsertStarted",80);raw.setLong("TokenInsertionSequence",11);if(occupied)raw.setTag("InsertedToken",new ItemStack(chip?ModItems.DATA_CHIP:ModItems.ACCESS_CARD,1,2).writeToNBT(new NBTTagCompound()));if(returning)raw.setUniqueId("TokenReturnTo",new java.util.UUID(17,29));tile.readFromNBT(raw);ItemStack input=input(chip,choice,count),before=input.copy(),result=ItemStack.EMPTY;InvWrapper wrapper=new InvWrapper(tile);boolean valid=tile.isItemValidForSlot(0,input);
    String failure=null;try{switch(op){case "set":tile.setInventorySlotContents(0,input);break;case "setInvalid":tile.setInventorySlotContents(1,input);break;case "decrZero":result=tile.decrStackSize(0,0);break;case "decrOne":result=tile.decrStackSize(0,1);break;case "decrMany":result=tile.decrStackSize(0,64);break;case "remove":result=tile.removeStackFromSlot(0);break;case "clear":tile.clear();break;case "insertSimulate":result=wrapper.insertItem(0,input,true);break;case "insert":result=wrapper.insertItem(0,input,false);break;case "extractSimulate":result=wrapper.extractItem(0,64,true);break;case "extract":result=wrapper.extractItem(0,64,false);break;default:throw new AssertionError(op);}}catch(RuntimeException error){failure=error.getClass().getSimpleName();}
    if(!ItemStack.areItemStacksEqual(input,before))throw new AssertionError("Inventory caller input mutated");NBTTagCompound saved=tile.writeToNBT(new NBTTagCompound());JsonObject row=new JsonObject();row.addProperty("chip",chip);row.addProperty("behavior",behavior);row.addProperty("filter",filter);row.addProperty("returning",returning);row.addProperty("occupied",occupied);row.addProperty("choice",choice);row.addProperty("count",count);row.addProperty("op",op);row.addProperty("valid",valid);if(failure!=null)row.addProperty("failure",failure);row.add("result",stack(result));row.add("owned",stack(tile.getStackInSlot(0)));row.addProperty("output",tile.getOutputLevel());row.addProperty("sequence",tile.insertionSequence());row.addProperty("started",tile.insertionStarted());row.addProperty("pulseUntil",saved.getLong("TokenPulseUntil"));row.addProperty("returningAfter",tile.returning());row.addProperty("limit",tile.getInventoryStackLimit());row.addProperty("size",tile.getSizeInventory());rows.add(row);
   }
  }
  String json=new Gson().toJson(rows);java.security.MessageDigest digest=java.security.MessageDigest.getInstance("SHA-256");StringBuilder hash=new StringBuilder();for(byte b:digest.digest(json.getBytes("UTF-8")))hash.append(String.format("%02x",b&255));if(!hash.toString().equals("cffe01e43dfc12ba9502e9c9e02e76e9777beff4e8b6b375bb8a737d25e95105"))throw new AssertionError("Released reader inventory changed "+hash);JsonObject root=new JsonObject();root.addProperty("schema",1);root.addProperty("golden",hash.toString());root.add("cases",rows);JsonArray hopper=hoppers();StringBuilder hopperHash=new StringBuilder();for(byte b:digest.digest(new Gson().toJson(hopper).getBytes("UTF-8")))hopperHash.append(String.format("%02x",b&255));if(!hopperHash.toString().equals("db18dbd532c9fd01d5ee1a679cf01800f86c98e874eec612cbe738e8887f4662"))throw new AssertionError("Released reader hopper changed "+hopperHash);root.addProperty("hopperGolden",hopperHash.toString());root.add("hopper",hopper);Path path=Paths.get(System.getProperty("vandorlabs.standaloneReaderInventoryReference","build/test-artifacts/standalone-reader-inventory-forge.json"));Files.createDirectories(path.toAbsolutePath().getParent());try(java.io.Writer writer=Files.newBufferedWriter(path)){new Gson().toJson(root,writer);}System.out.println("Actual standalone reader inventory PASS cases="+rows.size()+" golden="+hash+" hopperCases="+hopper.size()+" hopperGolden="+hopperHash);
 }
}
